using NUnit.Framework;
using Seqeron.Mcp.Analysis.Tools;

namespace Seqeron.Mcp.Analysis.Tests;

// <auto-generated by scripts/docs/gen_emboss_wp62_tools.py: do not edit> B09 WP62 (F281): the MCP tools of the EMBOSS programs; the expected text is what the installed EMBOSS 6.6.0 program writes for the example of the tool document (the clock of the random programs fixed).
[TestFixture]
public class EmbossProgramTools2Tests
{
    [Test]
    public void Shuffleseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Shuffleseq(">s1 d\nACGTACGTACGTAAAACCCGGGTTT\n", shuffle: 2, microseconds: 7);
        Assert.That(r.Text, Is.EqualTo(">s1 d\nAGGCTCGTCCGAATTGTTCAGACAA\n>s1 d\nAACGAAATCCCAGTGTGGTTCATGC\n"));
    }

    [Test]
    public void Msbar_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Msbar(">s1 d\nACGTACGTACGTAAAACCCGGGTTT\n", count: 3, point: "2,3", microseconds: 7);
        Assert.That(r.Text, Is.EqualTo(">s1 d\nACGTAGTACGCATAAACCCGGGTTT\n"));
    }

    [Test]
    public void Makenucseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Makenucseq(amount: 2, length: 20, microseconds: 7);
        Assert.That(r.Text, Is.EqualTo(">EMBOSS_001\ntcactctggtccagtttgcc\n>EMBOSS_002\ncgcaagcttagactaaaatt\n"));
    }

    [Test]
    public void Makeprotseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Makeprotseq(amount: 2, length: 12, microseconds: 7);
        Assert.That(r.Text, Is.EqualTo(">EMBOSS_001\nwhdhyktqmtli\n>EMBOSS_002\namsvsphggmgd\n"));
    }

    [Test]
    public void Nthseqset_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Nthseqset(">a\nAC\n>b\nGT\n", number: 1);
        Assert.That(r.Text, Is.EqualTo(">a\nAC\n>b\nGT\n"));
    }

    [Test]
    public void Listor_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Listor(">a\nAC\n>b\nGT\n", secondSequences: ">c\nac\n>d\nTT\n", @operator: "AND");
        Assert.That(r.Text, Is.EqualTo("fasta::firstsequences.dat:a\n"));
    }

    [Test]
    public void Infoseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Infoseq(">a desc here\nACGTACGTAC\n>b\nMKVLAAGIV\n");
        Assert.That(r.Text, Is.EqualTo("USA                      Database  Name           Accession      Type Length %GC    Organism            Description \nfasta::sequence.dat:a    -              a              -              N    10     50.00                      desc here\nfasta::sequence.dat:b    -              b              -              P    9                          \n"));
    }

    [Test]
    public void Wordcount_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Wordcount(">a\nACGTACGTACGTTTTT\n", wordSize: 3);
        Assert.That(r.Text, Is.EqualTo("TTT\t3\nCGT\t3\nACG\t3\nTAC\t2\nGTA\t2\nGTT\t1\n"));
    }

    [Test]
    public void Seqxref_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Seqxref("ID   TEST_HUMAN    Reviewed;    10 AA.\nAC   P12345;\nDR   PDB; 1ABC; X-ray; 1.9 A; A=1-10.\nDR   EMBL; X1234; -.\nSQ   SEQUENCE   10 AA;  1000 MW;  ABCD CRC64;\n     MKVLAAGIVG\n//\n");
        Assert.That(r.Text, Is.EqualTo("#swiss::sequence.dat:TEST_HUMAN: 2\nEMBL:X1234\nPDB:1ABC\n"));
    }

    [Test]
    public void Showorf_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Showorf(">s1 d\nATGAAATTTGGGCCCTAGATGCCCAAATTT\n", frames: "1,4", width: 30);
        Assert.That(r.Text, Is.EqualTo("SHOWORF of s1 from 1 to 30\n\n           ---------|---------|---------|\n         1 ATGAAATTTGGGCCCTAGATGCCCAAATTT 30\nF1       1 M  K  F  G  P  *  M  P  K  F   4\nR1      10   H  F  K  P  G  L  H  G  F  K 1\n\n"));
    }

    [Test]
    public void Prettyseq_WritesWhatTheInstalledProgramWrites()
    {
        var r = AnalysisTools.Prettyseq(">s1 d\nATGAAATTTGGGCCCTAGATGCCCAAATTT\n", range: "4-15");
        Assert.That(r.Text, Is.EqualTo("PRETTYSEQ of s1 from 1 to 30\n\n           ---------|---------|---------|\n         1 ATGaaatttgggcccTAGATGCCCAAATTT 30\n         1    K  F  G  P                  4\n\n"));
    }

    [Test]
    public void Tools_RefuseAnEmptySequenceAndABadValueWithTheMessagesOfTheLibrary()
    {
        Assert.Throws<ArgumentException>(() => AnalysisTools.Shuffleseq(""));
        var e = Assert.Throws<ArgumentException>(() => AnalysisTools.Msbar(">s1\nACGTACGT\n", point: "7"));
        Assert.That(e!.Message, Does.Contain("Bad menu option '7'"));
        var f = Assert.Throws<ArgumentException>(() => AnalysisTools.Makenucseq(amount: 1, length: 2, insert: "ACGTA"));
        Assert.That(f!.Message, Does.Contain("Sequence smaller than inserted part"));
    }
}
